SELECT t.id::text,ph.ordinal phase_ordinal,ph.title phase_title,t.title,t.description,t.status,t.checkbox_checked,s.path source_path,t.source_line FROM tasks t JOIN projects p ON p.id=t.project_id LEFT JOIN phases ph ON ph.id=t.phase_id LEFT JOIN plans pl ON pl.id=ph.plan_id LEFT JOIN source_documents s ON s.id=t.source_document_id WHERE p.slug=$1 AND t.status<>'cancelled' AND ((t.phase_id IS NULL AND (t.source_document_id IS NULL OR EXISTS(SELECT 1 FROM plans src_plan WHERE src_plan.source_document_id=t.source_document_id AND src_plan.is_current))) OR pl.is_current) ORDER BY ph.ordinal NULLS LAST,t.source_line NULLS LAST,t.created_at,t.id
